	# Mockup'larda kitle ve ödeyen ölçüsü yok: canlı B2C'nin ölçüleri live:b2c_live'da.
	return {"name": product, "live_version": "1.4", "market": market, "type_text": type_text, "users": -1, "paying": -1}


